package com.dukankhata.closing;
import com.dukankhata.product.Product; import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="daily_closing_items") public class DailyClosingItem { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="closing_id",nullable=false) private DailyClosing closing; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(nullable=false,length=120) private String productNameSnapshot; @Column(nullable=false,precision=12,scale=2) private BigDecimal unitPriceSnapshot; @Column(nullable=false,precision=12,scale=3) private BigDecimal quantity; @Column(nullable=false,precision=14,scale=2) private BigDecimal amount; public UUID getId(){return id;} public DailyClosing getClosing(){return closing;} public Product getProduct(){return product;} public String getProductNameSnapshot(){return productNameSnapshot;} public BigDecimal getUnitPriceSnapshot(){return unitPriceSnapshot;} public BigDecimal getQuantity(){return quantity;} public BigDecimal getAmount(){return amount;} public void setClosing(DailyClosing v){closing=v;} public void setProduct(Product v){product=v;} public void setProductNameSnapshot(String v){productNameSnapshot=v;} public void setUnitPriceSnapshot(BigDecimal v){unitPriceSnapshot=v;} public void setQuantity(BigDecimal v){quantity=v;} public void setAmount(BigDecimal v){amount=v;} }
